import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {indicatorColour,phClass} from './saltph-models.js?v=20261023-physicscomplete01';
export function showSaltPh(kind,t=null,reveal=false){if(kind==='ph'){const v=typeof t==='number'?t:7,[name,colour]=indicatorColour(v);renderDiagram('Read the pH scale','0–14 · course conditions',`<div class="inventory-board"><span class="eyebrow">SCHEMATIC UNIVERSAL-INDICATOR CHART</span><div class="ph-colour" style="background:${colour}"><b>pH ${v}</b><span>${name}</span></div><div class="ph-gradient" role="img" aria-label="pH scale from acidic at0 through neutral7 to alkaline14"><i style="left:${v/14*100}%"></i></div><div class="ph-labels"><span>0 · acidic</span><span>7 · neutral</span><span>14 · alkaline</span></div><p class="inventory-outcome">${reveal?phClass(v):'Explore the scale, then classify the target'}</p><p class="diagram-caption">Illustrative colour chart; real indicator colours vary. Match the supplied chart for approximate pH.</p></div>`,'COLOUR PLUS LABELS · NOT EXACT MEASUREMENT');return;}
renderDiagram('Reaction → pure, dry crystals',t?.salt||'Plan the excess-solid method',`<div class="inventory-board"><span class="eyebrow">SCHOOL PRACTICAL PREPARATION</span><div class="inventory-row"><span>${t?.acid||'Acid supplies the negative ion'}</span><small>${t?.solid||'Insoluble oxide/carbonate supplies the metal ion'}</small></div><p class="inventory-outcome">${reveal?'Excess → filter → concentrate → cool → dry':'Build the sequence before revealing it'}</p><p class="diagram-caption">A method planner, not apparatus or completion of the required school practical.</p></div>`,'EXPLAIN EACH STEP · PRESERVE PURITY');}
